<?xml version="1.0" encoding="UTF-8" standalone="no"?>
<mappingRoot xmlns="http://www.ibm.com/2008/ccl/Mapping" xmlns:map="default" domainID="com.ibm.msl.mapping.xml" domainIDExtension="mb" mainMap="true" targetNamespace="default" version="8.0.5.0">
    <input path="jar:file://!com/ibm/etools/mft/map/xsds/predefined/JsonDomainMsg.xsd" var="var"/>
    <input derivedFrom="MB:JSON_schema_in_swagger_document" path="/openapi.json" var="var1"/>
    <output path="mbsharedlib://SchoolServicesLib/StudentInfo.xsd"/>
    <namespaces>
        <namespace kind="supplement" prefix="in" uri="http://www.ibm.com/iib/msl/json"/>
    </namespaces>
    <generation engine="xquery"/>
    <mappingDeclaration name="postStudent_Mapping">
        <input namespace="http://www.ibm.com/iib/msl/json" path="$var/mb:msg(JSON,assembly,JSON,Properties)" var="ComIbmMessageAssembly_JSON">
            <cast derivedFrom="MB:JSON_operation_request" path="$ComIbmMessageAssembly_JSON/JSON/Data/type('anyType')" qualifier="{http://www.ibm.com/iib/msl/json}object_postStudent_body" ref="var1"/>
        </input>
        <output path="mb:msg(student,assembly,XMLNSC,Properties)" var="ComIbmMessageAssembly_student"/>
        <move>
            <input path="$ComIbmMessageAssembly_JSON/Properties"/>
            <output path="$ComIbmMessageAssembly_student/Properties"/>
            <override>
                <assign value="{SchoolServicesLib}">
                    <output path="$ComIbmMessageAssembly_student/Properties/MessageSet"/>
                </assign>
            </override>
        </move>
        <move>
            <input path="$ComIbmMessageAssembly_JSON/JSON/spath('Data',2)/studentId"/>
            <output path="$ComIbmMessageAssembly_student/student/studentId"/>
        </move>
        <move>
            <input path="$ComIbmMessageAssembly_JSON/JSON/spath('Data',2)/firstName"/>
            <output path="$ComIbmMessageAssembly_student/student/firtName"/>
        </move>
        <move>
            <input path="$ComIbmMessageAssembly_JSON/JSON/spath('Data',2)/lastName"/>
            <output path="$ComIbmMessageAssembly_student/student/lastName"/>
        </move>
        <move>
            <input path="$ComIbmMessageAssembly_JSON/JSON/spath('Data',2)/dob"/>
            <output path="$ComIbmMessageAssembly_student/student/dateOfBirth"/>
        </move>
        <move>
            <input path="$ComIbmMessageAssembly_JSON/JSON/spath('Data',2)/studentEmail"/>
            <output path="$ComIbmMessageAssembly_student/student/studentEmail"/>
        </move>
        <move>
            <input path="$ComIbmMessageAssembly_JSON/JSON/spath('Data',2)/guardianContactName"/>
            <output path="$ComIbmMessageAssembly_student/student/guardianContactName"/>
        </move>
        <move>
            <input path="$ComIbmMessageAssembly_JSON/JSON/spath('Data',2)/guardianContactNo"/>
            <output path="$ComIbmMessageAssembly_student/student/guardianContactNo"/>
        </move>
    </mappingDeclaration>
</mappingRoot>
